INSERT INTO "content_overrides" VALUES(5,NULL,'principal','vision.text','إعداد طالبٍ مؤمنٍ بدينه، منتمٍ لوطنه، ومسلَّحٍ بالإيمان والعلم؛ لتمكينه من مواجهة تحديات العصر.
','2026-10-15 04:55:13');
INSERT INTO "content_overrides" VALUES(6,NULL,'principal','introduction.signature.name','نايف بن سمير المخلفي','2026-10-15 05:37:49');
INSERT INTO "content_overrides" VALUES(7,NULL,'principal','introduction.signature.title','مدير مدرسة','2026-10-15 05:37:49');
INSERT INTO "content_overrides" VALUES(8,NULL,'principal','strategic_goals.goals','[{"text":"تطوير منظومة القيادة المدرسية وتفعيل التخطيط الاستراتيجي المبني على البيانات.","indicators":[{"kpi":"نسبة اعتماد الخطط التشغيلية في وقتها","target":"100%","measurement":""},{"kpi":"نسبة تنفيذ البرامج التطويرية","target":"90%","measurement":""},{"kpi":"مؤشر جديد","target":"100%","measurement":""},{"kpi":"نسبة الحضور","target":"95%","measurement":"فصلي"},{"kpi":"نسبة التاخر","target":"1%","measurement":"فصلي"}],"programs":["برنامج التخطيط الاستراتيجي المدرسي","برنامج المؤشرات والمتابعة الدورية","برنامج تقويم الأداء المؤسسي","برنامج تجريبي","برنامج مواهب وأفكار "]},{"text":"تحسين جودة عمليات التعليم والتعلم من خلال بناء خبرات تعلمية فاعلة وتقويم مستمر.","indicators":[{"kpi":"نسبة المعلمين المطبقين للاستراتيجيات الحديثة","target":"85%","measurement":""},{"kpi":"نسبة تطبيق الاختبارات التشخيصية القبلية والبعدية","target":"100%","measurement":""}],"programs":["برنامج الزيارات الصفية الاستطلاعية والتقويمية","برنامج مجتمعات التعلم المهنية (PLCs)","برنامج الاختبارات التشخيصية والعلاجية","برنامج تبادل الزيارات بين المعلمين"]},{"text":"رفع مستوى التحصيل العلمي للطلاب وتحسين نتائجهم في الاختبارات الوطنية (نافس).","indicators":[{"kpi":"نسبة تحسن نتائج الطلاب في نافس","target":"+10% عن العام السابق","measurement":""},{"kpi":"نسبة الطلاب المتفوقين","target":"20%","measurement":""}],"programs":["برنامج نافس للاستعداد للاختبارات الوطنية","برنامج رعاية المتفوقين والموهوبين","برنامج معالجة الفاقد التعليمي","برنامج حصص الدعم والتقوية"]},{"text":"توفير بيئة مدرسية آمنة وصحية محفزة على التعلم وفق معايير الأمن والسلامة.","indicators":[{"kpi":"نسبة تنفيذ فرضيات الإخلاء الدورية","target":"100% (3 فرضيات سنويًا)","measurement":""},{"kpi":"نسبة رضا الطلاب عن البيئة المدرسية","target":"90%","measurement":""}],"programs":["برنامج فرضيات الإخلاء الدورية","برنامج مسعف في كل مدرسة","برنامج التوعية بمخاطر السلامة","برنامج صيانة المبنى والمرافق"]},{"text":"تعزيز السلوك الإيجابي والصحة النفسية والجسدية للطلاب.","indicators":[{"kpi":"نسبة انخفاض حالات الغياب والسلوك","target":"-30%","measurement":""},{"kpi":"نسبة مشاركة الطلاب في البرامج الوقائية","target":"80%","measurement":""}],"programs":["برنامج انضباطي سر تميزي","برنامج رفق لخفض العنف المدرسي","برنامج حصين وحماية للتوعية بأضرار المخدرات","برنامج الصحة المدرسية والفحص الاستكشافي"]},{"text":"تطوير الكوادر التعليمية والإدارية مهنيًا وتحسين كفاءتهم.","indicators":[{"kpi":"نسبة حضور المعلمين للبرامج التدريبية","target":"100%","measurement":""},{"kpi":"نسبة تحسن الأداء الوظيفي","target":"85%","measurement":""}],"programs":["برنامج التطوير المهني الداخلي","برنامج تدريب المعلمين الجدد","برنامج الدروس التطبيقية ونقل الخبرة"]},{"text":"تعزيز الشراكة المجتمعية مع أولياء الأمور والمؤسسات المحلية.","indicators":[{"kpi":"نسبة حضور أولياء الأمور للاجتماعات","target":"70%","measurement":""},{"kpi":"عدد الشراكات المجتمعية الفاعلة","target":"5 شراكات سنويًا","measurement":""}],"programs":["برنامج لقاء الشراكة مع أولياء الأمور","برنامج رائد الشراكة المجتمعية (ارتقاء)"]}]','2026-10-15 05:37:49');
