CREATE TABLE noor_timetable (
                id INTEGER PRIMARY KEY,
                day TEXT,
                period TEXT,
                subject TEXT,
                teacher TEXT,
                classroom TEXT,
                updated_at TEXT
            , is_deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE phrase_bank (
                id INTEGER PRIMARY KEY,
                category TEXT NOT NULL,
                sub_category TEXT NOT NULL,
                field_name TEXT NOT NULL,
                template_text TEXT NOT NULL,
                variables TEXT,
                sort_order INTEGER,
                created_at TEXT,
                UNIQUE(category, sub_category, field_name, template_text)
            );
INSERT INTO "phrase_bank" VALUES(1,'سلوكي','مخالفة سلوكية','الوصف','رُصدت مخالفة سلوكية للطالب {{اسم_الطالب}} في {{التاريخ_الهجري}}، تتمثل في {{نوع_المخالفة}}، وتم توثيق الواقعة وفق لائحة السلوك والمواظبة.','["اسم_الطالب", "التاريخ_الهجري", "نوع_المخالفة"]',1,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(2,'سلوكي','مخالفة سلوكية','الإجراء','اتُّخذ إجراء تربوي مع {{اسم_الطالب}} يتمثل في {{الإجراء_التربوي}}، مع إشعار ولي الأمر ومتابعة الالتزام خلال أسبوع.','["اسم_الطالب", "الإجراء_التربوي"]',2,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(3,'سلوكي','غياب متكرر','الوصف','تبيّن تكرار غياب الطالب {{اسم_الطالب}} بنسبة تتجاوز الحد المقبول، ويستدعي ذلك دراسة الحالة وتعزيز الشراكة مع الأسرة.','["اسم_الطالب"]',3,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(4,'سلوكي','غياب متكرر','ملاحظة الشاهد','شاهد المتابعة: محضر تواصل مع ولي أمر {{اسم_الطالب}} بتاريخ {{التاريخ_الميلادي}}، وخطة التزام موقّعة إن وُجدت.','["اسم_الطالب", "التاريخ_الميلادي"]',4,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(5,'سلوكي','تأخر صباحي','الوصف','رُصد تأخر صباحي للطالب {{اسم_الطالب}} في {{التاريخ_الهجري}}، ويُتابع ضمن سجل المواظبة مع إشعار الأسرة.','["اسم_الطالب", "التاريخ_الهجري"]',5,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(6,'أكاديمي','فاقد تعليمي','الوصف','يحتاج {{اسم_الطالب}} إلى معالجة فاقد تعليمي في {{المادة}} بناءً على نتيجة التشخيص القبلي، ضمن برنامج الدعم المعتمد.','["اسم_الطالب", "المادة"]',6,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(7,'أكاديمي','فاقد تعليمي','الإجراء','يُنفَّذ تدخل علاجي مركّز للطالب {{اسم_الطالب}} في {{المادة}} عبر حصص دعم وقياس بعدي موثّق.','["اسم_الطالب", "المادة"]',7,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(8,'أكاديمي','رعاية موهوبين','الوصف','يُرشَّح {{اسم_الطالب}} لبرامج رعاية الموهبة والإثراء وفق محكات الترشيح المعتمدة، مع خطة متابعة فصلية.','["اسم_الطالب"]',8,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(9,'أكاديمي','تفكير عليا','الوصف','تُضمَّن في حصة {{المادة}} مهمة تفكير عليا (تحليل/تقويم/إبداع) ويُوثَّق أثرها في أعمال الطلاب.','["المادة"]',9,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(10,'أكاديمي','نافس','ملاحظة الشاهد','شاهد الاستعداد لنافس: محاكاة بتاريخ {{التاريخ_الميلادي}} مع تحليل المهارات الأضعف وخطة مراجعة أسبوعية.','["التاريخ_الميلادي"]',10,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(11,'إداري','متابعة يومية','الوصف','مهمة يوم {{التاريخ_الهجري}} / {{التاريخ_الميلادي}}: {{عنوان_المهمة}}، وتُغلق بعد التحقق من الشاهد المطلوب.','["التاريخ_الهجري", "التاريخ_الميلادي", "عنوان_المهمة"]',11,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(12,'إداري','متابعة يومية','ملاحظة الشاهد','الشاهد المطلوب للمهمة «{{عنوان_المهمة}}»: {{نوع_الشاهد}}، مؤرّخ في {{التاريخ_الميلادي}}.','["عنوان_المهمة", "نوع_الشاهد", "التاريخ_الميلادي"]',12,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(13,'إداري','شراكة مجتمعية','الوصف','تفعيل شراكة مجتمعية لدعم التعلم مع {{اسم_الشريك}} بهدف {{هدف_الشراكة}}، وربط الأثر بمؤشر 1-3-1-3.','["اسم_الشريك", "هدف_الشراكة"]',13,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(14,'إداري','أمن وسلامة','الوصف','تنفيذ إجراء أمن وسلامة متعلق بـ {{موضوع_السلامة}} في {{التاريخ_الهجري}}، مع توثيق المحضر في سجل البيئة.','["موضوع_السلامة", "التاريخ_الهجري"]',14,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(15,'تقويم','خطة تحسين','الوصف','متابعة إجراء التحسين «{{عنوان_الإجراء}}» المرتبط بالمؤشر {{رمز_المؤشر}}، وفق الموعد {{التاريخ_الميلادي}}.','["عنوان_الإجراء", "رمز_المؤشر", "التاريخ_الميلادي"]',15,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(16,'تقويم','خطة تحسين','ملاحظة الشاهد','شاهد إجراء التحسين {{عنوان_الإجراء}}: {{نوع_الشاهد}}، ويُرفق قبل إغلاق المهمة.','["عنوان_الإجراء", "نوع_الشاهد"]',16,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(17,'تقويم','زيارة صفية','الوصف','زيارة صفية لـ {{اسم_المعلم}} في مادة {{المادة}}، مع تركيز على استراتيجيات التدريس ومهارات التفكير العليا.','["اسم_المعلم", "المادة"]',17,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(18,'شاهد','تنفيذ برنامج','ملاحظة الشاهد','تم تنفيذ برنامج «{{اسم_البرنامج}}» يوم {{التاريخ_الهجري}}، والشاهد: {{نوع_الشاهد}} مع بيان المستفيدين والأثر.','["اسم_البرنامج", "التاريخ_الهجري", "نوع_الشاهد"]',18,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(19,'شاهد','اعتماد سجل','ملاحظة الشاهد','اعتماد {{اسم_السجل}} ليوم {{التاريخ_الميلادي}} بعد اكتمال الرصد والمراجعة.','["اسم_السجل", "التاريخ_الميلادي"]',19,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(20,'شاهد','تعلم إلكتروني','ملاحظة الشاهد','توثيق تفعيل منصة مدرستي للدرس «{{عنوان_الدرس}}» بتاريخ {{التاريخ_الميلادي}} عبر {{نوع_الشاهد}}.','["عنوان_الدرس", "التاريخ_الميلادي", "نوع_الشاهد"]',20,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(21,'محضر','مجلس مدرسي','الوصف','انعقد {{نوع_المجلس}} بتاريخ {{التاريخ_الهجري}} الموافق {{التاريخ_الميلادي}} برئاسة {{اسم_الرئيس}}، ونوقشت البنود المعتمدة في جدول الأعمال.','["نوع_المجلس", "التاريخ_الهجري", "التاريخ_الميلادي", "اسم_الرئيس"]',21,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(22,'محضر','مجلس مدرسي','الإجراء','أوصى المجلس بـ {{نص_التوصية}}، على أن تُتابع من {{الجهة_المنفذة}} قبل {{تاريخ_المتابعة}}.','["نص_التوصية", "الجهة_المنفذة", "تاريخ_المتابعة"]',22,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(23,'محضر','لجنة إدارية','الوصف','ناقشت اللجنة الإدارية موضوع «{{موضوع_الاجتماع}}» واتخذت ما يلزم وفق صلاحياتها، مع توثيق الحضور والتوصيات.','["موضوع_الاجتماع"]',23,'2026-10-30T13:27:35+00:00');
INSERT INTO "phrase_bank" VALUES(24,'محضر','فحص مظروف أسئلة','الوصف','تم فحص مظروف أسئلة {{المادة}} للصف {{الصف}} بحضور اللجنة المختصة، وتبيّن {{نتيجة_الفحص}} مع التوقيع على المحضر.','["المادة", "الصف", "نتيجة_الفحص"]',24,'2026-10-30T13:27:35+00:00');
