CREATE TABLE program_templates (
                id INTEGER PRIMARY KEY,
                template_key TEXT NOT NULL UNIQUE,
                label TEXT NOT NULL,
                program_name TEXT NOT NULL,
                strategic_goal TEXT,
                executive_goal TEXT,
                target_audience TEXT,
                duration TEXT,
                implementers TEXT,
                budget TEXT,
                mechanism TEXT,
                success_indicator TEXT,
                risk_management TEXT,
                register_id INTEGER,
                owner_role TEXT,
                indicator_codes TEXT,
                sort_order INTEGER
            , owner_roles TEXT, goal_ref TEXT);
INSERT INTO "program_templates" VALUES(1,'loss','معالجة الفاقد','معالجة الفاقد التعليمي والرفع التحصيلي','رفع مستوى التحصيل العلمي للطلاب وتحسين نتائجهم في الاختبارات الوطنية (نافس).','ردم الفجوة التعليمية وتتبع مهارات نافس الحرجة في القراءة والرياضيات والعلوم.','الطلاب الحاصلون على تقدير دون المتوسط في الاختبارات التشخيصية','الأسابيع الستة الأولى من الفصل الدراسي','معلمو المواد المستهدفة تحت إشراف وكيل الشؤون التعليمية','ذاتية، بالاعتماد على المصادر الرقمية لوزارة التعليم','1. تطبيق اختبار تشخيصي قبلي وتحديد الفجوة وتوثيقها بنموذج (ت-1).
2. بناء خطة التحسين واستمارة البناء لواقع الفصول بنموذج (ت-2).
3. تنفيذ مراجعات تدريسية مركزة في الدقائق العشر الأولى من كل حصة لمهارات نافس الحرجة بنموذج (ت-3).
4. إجراء اختبار محاكاة بعدي لقياس الأثر وتوثيق الشواهد في سجل المناهج والتقويم.','انتقال 80% من الطلاب المستهدفين إلى مستوى متوسط فأعلى','في حال غياب الطالب تُفعَّل الموديولات العلاجية الرقمية عبر منصة مدرستي وتُرسل لولي الأمر',3,'vice_teachers','["3-1-1-1", "3-1-1-2"]',1,'["vice_teachers"]','G3');
INSERT INTO "program_templates" VALUES(2,'discipline','الانضباط','تعزيز الانضباط المدرسي والحد من الغياب','تعزيز السلوك الإيجابي والصحة النفسية والجسدية للطلاب.','خفض نسبة الغياب غير المبرر وتعزيز الالتزام بقواعد السلوك والمواظبة','جميع طلاب المدرسة (مع تركيز على متكرري الغياب)','مستمر طوال العام الدراسي','وكيل شؤون الطلاب، الموجه الطلابي، رواد الفصول','500 ريال للجوائز العينية وشهادات التقدير للفصول المتميزة','1. رصد الغياب في الحصة الأولى يومياً وإدخاله في نور ونموذج الرصد (ط-1) قبل الساعة التاسعة صباحاً.
2. إرسال رسائل لولي الأمر وتحديث سجل تتبع المواظبة أسبوعياً.
3. تحويل الحالات التي تتجاوز غياب 5% للموجه الطلابي لدراسة الحالة بنموذج (ط-2) وتوقيع عقد شراكة سلوكية.
4. تكريم الفصول ذات الغياب الصفري أسبوعياً وتوثيق الشواهد في سجل الانضباط.','تحقيق نسبة انضباط عامة لا تقل عن 96% طوال العام الدراسي','عدم تجاوب ولي الأمر يرتب عليه تطبيق لائحة قواعد السلوك والمواظبة وتصعيد الإجراء',4,'vice_students','["3-2-1-5", "1-2-1-4"]',2,'["vice_students", "student_counselor"]','G5');
INSERT INTO "program_templates" VALUES(3,'career','التوجيه المهني','التوجيه المهني والتعليمي','تعزيز السلوك الإيجابي والصحة النفسية والجسدية للطلاب.','تمكين طلاب الثالث متوسط من اختيار مسار ثانوي مناسب وفق الميول والقدرات','طلاب الصف الثالث المتوسط','الفصل الدراسي الثاني','الموجه الطلابي بالتنسيق مع وكيل شؤون الطلاب ورواد الفصول','ذاتية (مقاييس ميول مطبوعة / مواد توعية)','1. تطبيق مقياس ميول مهنية لطلاب الثالث متوسط وتوثيق النتائج في سجل التوجيه.
2. جلسات إرشاد فردية وجماعية حول مسارات الثانوية (عام / مقررات / مهني) وفق نتائج المقياس.
3. لقاء أولياء أمور الصف الثالث لشرح المسارات ومتطلبات القبول.
4. زيارة افتراضية أو ميدانية لمؤسسة تعليمية/مهنية محلية وتوثيق الأثر باستمارة رضا.','إكمال 100% من طلاب الثالث متوسط لمقياس الميول وجلسة توجيه واحدة على الأقل','ضعف حضور أولياء الأمور يُعوَّض برسالة فردية ومحتوى رقمي عبر منصة مدرستي',5,'student_counselor','["3-2-1-6", "1-3-1-2"]',3,'["student_counselor", "vice_students"]','G5');
INSERT INTO "program_templates" VALUES(4,'gifted','رعاية الموهوبين','رعاية الموهوبين والمبتكرين','رفع مستوى التحصيل العلمي للطلاب وتحسين نتائجهم في الاختبارات الوطنية (نافس).','اكتشاف الموهوبين وتوفير فرص إثراء عادلة تدعم الابتكار والتفوق','الطلاب الموهوبون','مستمر طوال العام الدراسي','رائد النشاط، معلمو المواد، الموجه الطلابي تحت إشراف وكيل الشؤون التعليمية','من ميزانية النشاط وبرامج موهبة المتاحة','1. ترشيح المعلمين وفق محكات الموهبة المعتمدة وحصر المرشحين في سجل رعاية الموهوبين.
2. إثراء أسبوعي (بحث / مشروع / مسابقة) داخل الصف وخارجه مع معلم المادة.
3. مشاركة الطلاب المرشحين في برامج موهبة أو مسابقات الوزارة حسب المتاح.
4. تقويم فصلي لمستوى الإنجاز وتحديث خطة الرعاية في السجل.','خطة رعاية موثّقة لـ 100% من المرشحين ومشاركة 70% منهم في نشاط إثرائي فصلي على الأقل','نقص المقاعد في برامج موهبة يُعوَّض بإثراء داخلي ومسابقات مدرسية موثّقة',5,'activity_leader','["1-2-1-5", "2-1-1-1"]',4,'["activity_leader"]','G3');
INSERT INTO "program_templates" VALUES(5,'partnership','الشراكة المجتمعية','الشراكة المجتمعية لدعم التعلم','تعزيز الشراكة المجتمعية مع أولياء الأمور والمؤسسات المحلية.','بناء شراكات فاعلة تدعم التعلم والعمل التطوعي والتأثير الإيجابي في المجتمع المحلي','أولياء الأمور، المجتمع المحلي','مستمر طوال العام الدراسي','مدير المدرسة، رائد النشاط، مجلس أولياء الأمور','ذاتية / دعم الشركاء وفق الاتفاقيات','1. حصر احتياجات التعلم والشراكات المطلوبة وربطها بهدف G7 في الخطة التشغيلية.
2. توقيع 3–5 شراكات محلية مكتوبة (أسرة، مركز صحي، مكتبة، بلدية أو كلية) بهدف تعليمي واضح.
3. تنفيذ لقاءات مجلس أولياء الأمور وبرامج ارتقاء وفق التقويم المعتمد.
4. قياس الأثر فصلياً (حضور، مستفيدون، أثر على التعلم/السلوك) ورفع تقرير للجنة الإدارية.','تحقيق 5 شراكات فاعلة سنوياً وحضور أولياء أمور لا يقل عن 70% في اللقاءات المعتمدة','تأخر توقيع الشراكة يُعالَج ببدائل مجتمعية موثّقة وخطة تواصل أسبوعية مع الأسر',5,'principal','["1-3-1-3", "3-2-1-4"]',5,'["principal", "activity_leader"]','G7');
INSERT INTO "program_templates" VALUES(6,'safety','الأمن والسلامة','الأمن والسلامة المدرسية','توفير بيئة مدرسية آمنة وصحية محفزة على التعلم وفق معايير الأمن والسلامة.','استيفاء متطلبات الأمن والسلامة وتنفيذ فرضيات الإخلاء وصيانة المرافق بانتظام','جميع المنسوبين والطلاب','مستمر طوال العام الدراسي','وكيل شؤون الطلاب، فريق الأمن والسلامة، محضر المختبر','صيانة وتشغيل وفق بنود المدرسة وطلبات الإدارة','1. فحص دوري لمتطلبات الأمن والسلامة في الفصول والمعامل والمرافق وتوثيقه في سجل البيئة.
2. تنفيذ فرضيات إخلاء مجدولة (ثلاث سنوياً على الأقل) مع محضر فريق الأمن والسلامة.
3. جدولة صيانة دورية للمرافق والتجهيزات ورفع نواقص الاشتراطات بخطاب رسمي.
4. حملات توعية للطلاب والمنسوبين وقياس رضا فصلي عن البيئة المدرسية.','تنفيذ 100% من فرضيات الإخلاء المجدولة ورفع نواقص السلامة بمحاضر رسمية','تأخر استجابة جهات الصيانة يُوثَّق رسمياً مع إجراءات مؤقتة للسلامة داخل المبنى',6,'vice_students','["4-2-1-1", "4-2-1-2", "4-2-1-3"]',6,'["vice_students", "principal"]','G4');
INSERT INTO "program_templates" VALUES(7,'nafs','نافس','نافس للاستعداد للاختبارات الوطنية','رفع مستوى التحصيل العلمي للطلاب وتحسين نتائجهم في الاختبارات الوطنية (نافس).','تهيئة الطلاب لاختبارات نافس عبر محاكاة وتمارين مهارات مستهدفة','طلاب الصفوف المستهدفة في نافس','قبل نافس وخلال فترات المراجعة المعتمدة','وكيل الشؤون التعليمية ومعلمو القراءة والرياضيات والعلوم','ذاتية / منصة مدرستي ونماذج الوزارة','1. تحليل نتائج نافس السابقة وتحديد المهارات الأضعف.
2. جدول مراجعة أسبوعي للمهارات الحرجة.
3. اختبارات محاكاة موثّقة مع تغذية راجعة.
4. تقرير أثر بعد كل محاكاة في سجل المناهج والتقويم.','تحسن متوسط المدرسة في نافس بنسبة لا تقل عن 10% عن العام السابق','ضعف حضور الطلاب للمراجعات يُعوَّض بواجبات رقمية ومتابعة ولي الأمر',3,'vice_teachers','["3-1-1-1", "3-1-1-2"]',7,'["vice_teachers"]','G3');
INSERT INTO "program_templates" VALUES(8,'support','الدعم والتقوية','حصص الدعم والتقوية','رفع مستوى التحصيل العلمي للطلاب وتحسين نتائجهم في الاختبارات الوطنية (نافس).','تقديم حصص تقوية مركزة للطلاب ذوي الأداء المنخفض وفق التشخيص','الطلاب الحاصلون على تقدير دون المتوسط في الاختبارات التشخيصية','فصلي وفق جدول الدعم المعتمد','معلمو المواد تحت إشراف وكيل الشؤون التعليمية','ذاتية','1. فرز المستهدفين من التشخيص.
2. مجموعات تقوية صغيرة بجدول ثابت.
3. قياس بعدي كل أربعة أسابيع.
4. توثيق الحضور والأثر في سجل المناهج والتقويم.','انتقال 70% من المستهدفين مستوىً تحصيلياً واحداً على الأقل','تعارض الجدول يُحل بإعادة جدولة مرنة أو دعم داخل الحصة',3,'vice_teachers','["3-1-1-2", "2-1-1-6"]',8,'["vice_teachers"]','G3');
INSERT INTO "program_templates" VALUES(9,'visits','الزيارات الصفية','الزيارات الصفية الاستطلاعية والتقويمية','تحسين جودة عمليات التعليم والتعلم من خلال بناء خبرات تعلمية فاعلة وتقويم مستمر.','متابعة جودة التدريس وتنمية مهارات التفكير العليا عبر زيارات صفية منتظمة','جميع معلمي المواد','مستمر وفق خطة الزيارات','وكيل الشؤون التعليمية ومدير المدرسة','ذاتية','1. خطة زيارات فصلية معلنة.
2. بطاقة ملاحظة تشمل استراتيجيات التدريس والتفكير العليا.
3. تغذية راجعة مكتوبة ومتابعة أثر.
4. رصد نسبة المعلمين المطبقين للاستراتيجيات المستهدفة.','تنفيذ 100% من الزيارات المخططة ووصول 85% من المعلمين لتطبيق الاستراتيجيات المستهدفة','ضغط الجدول يُعالَج بزيارات قصيرة مركّزة وإعادة الجدولة أسبوعياً',2,'vice_teachers','["2-1-1-3", "2-1-1-7", "2-2-1-3"]',9,'["vice_teachers"]','G2');
INSERT INTO "program_templates" VALUES(10,'plc','مجتمعات التعلم','مجتمعات التعلم المهنية (PLCs)','تحسين جودة عمليات التعليم والتعلم من خلال بناء خبرات تعلمية فاعلة وتقويم مستمر.','بناء مجتمعات تعلم مهنية أسبوعية تركز على تحسين نواتج الطلاب','مجتمعات معلمي المواد','مستمر طوال العام','وكيل الشؤون التعليمية وقادة المجتمعات','ذاتية','1. تشكيل مجتمعات حسب التخصص.
2. اجتماع أسبوعي بمحضر وهدف تعلّم.
3. تجربة صفية مشتركة وقياس أثر.
4. مشاركة النتائج في التطوير المهني.','عقد مجتمع تعلم واحد على الأقل لكل تخصص شهرياً مع محضر وأثر موثّق','ضعف الالتزام يُعالَج بربط الحضور بخطة التطوير المهني',2,'vice_teachers','["1-4-1-2", "2-1-1-3"]',10,'["vice_teachers"]','G2');
INSERT INTO "program_templates" VALUES(11,'evacuation','فرضيات الإخلاء','فرضيات الإخلاء الدورية','توفير بيئة مدرسية آمنة وصحية محفزة على التعلم وفق معايير الأمن والسلامة.','تنفيذ فرضيات إخلاء دورية وقياس زمن الخروج وتصحيح الملاحظات','جميع المنسوبين والطلاب','ثلاث فرضيات على الأقل خلال العام','فريق الأمن والسلامة ووكيل شؤون الطلاب','ذاتية','1. جدولة الفرضيات في التقويم المعتمد.
2. تنفيذ الفرضية بمحضر زمني.
3. معالجة الملاحظات خلال أسبوعين.
4. حفظ الشواهد في سجل البيئة والموارد.','تنفيذ 100% من الفرضيات المجدولة (3 سنوياً)','تعارض المناسبة يُعاد جدولته خلال أسبوع مع إشعار المنسوبين',6,'vice_students','["4-2-1-1"]',11,'["vice_students"]','G4');
INSERT INTO "program_templates" VALUES(12,'building','صيانة المبنى','صيانة المبنى والمرافق','توفير بيئة مدرسية آمنة وصحية محفزة على التعلم وفق معايير الأمن والسلامة.','تحسين ملاءمة المبنى والمرافق المساندة لاحتياجات المتعلمين بمن فيهم ذوو الإعاقة','جميع المنسوبين والطلاب','مستمر مع جولات شهرية','وكيل شؤون الطلاب ومدير المدرسة','طلبات صيانة رسمية + تشغيل ذاتي للنواقص البسيطة','1. جرد شهري للمرافق والفصول والمعامل.
2. رفع نواقص الاشتراطات والوصولية بخطابات رسمية.
3. تنفيذ تحسينات تنظيمية فورية داخل المدرسة.
4. متابعة إغلاق المعاملات وتوثيق قبل/بعد.','إغلاق 80% من ملاحظات الصيانة المرفوعة خلال الفصل وإخراج مؤشري المبنى من التهيئة','تأخر الجهة المختصة يُوثَّق مع إجراءات سلامة مؤقتة',6,'vice_students','["4-1-1-1", "4-1-1-3", "4-2-1-2"]',12,'["vice_students", "principal"]','G4');
INSERT INTO "program_templates" VALUES(13,'parent_meet','لقاء أولياء الأمور','لقاء الشراكة مع أولياء الأمور','تعزيز الشراكة المجتمعية مع أولياء الأمور والمؤسسات المحلية.','رفع مشاركة الأسرة في تعلم الأبناء ومتابعة التحصيل والسلوك','أولياء الأمور، المجتمع المحلي','لقاءات فصلية وفق التقويم','مدير المدرسة والموجه الطلابي ورواد الفصول','ذاتية','1. دعوة منظّمة عبر نور ووسائل التواصل.
2. عرض نتائج وتحصيل وخطة تحسين.
3. ورش قصيرة لأولياء الأمور.
4. قياس الحضور والأثر في محضر اللقاء.','حضور لا يقل عن 70% من أولياء الأمور المستدعين في اللقاءات المعتمدة','ضعف الحضور يُعوَّض بلقاءات فصول مصغّرة ومتابعة هاتفية',5,'principal','["1-3-1-2", "1-3-1-3"]',13,'["principal", "student_counselor"]','G7');
INSERT INTO "program_templates" VALUES(14,'irtiqaa','ارتقاء','رائد الشراكة المجتمعية (ارتقاء)','تعزيز الشراكة المجتمعية مع أولياء الأمور والمؤسسات المحلية.','تفعيل برنامج ارتقاء بشراكات مجتمعية تدعم التعلم','أولياء الأمور، المجتمع المحلي','مستمر وفق مبادرات ارتقاء','رائد النشاط ومدير المدرسة','دعم الشركاء / ذاتية','1. تسجيل المبادرات وفق ضوابط ارتقاء.
2. تنفيذ أنشطة مشتركة مع أثر تعليمي.
3. توثيق الشواهد والمستفيدين.
4. تقرير فصلي للجنة الإدارية.','تنفيذ مبادرتين ارتقاء على الأقل لكل فصل دراسي بأثر موثّق','اعتذار الشريك يُعوَّض بشريك بديل من قائمة الحصر',5,'activity_leader','["1-3-1-3"]',14,'["activity_leader", "principal"]','G7');
INSERT INTO "program_templates" VALUES(15,'volunteer','التطوع الطلابي','العمل التطوعي الطلابي','تعزيز الشراكة المجتمعية مع أولياء الأمور والمؤسسات المحلية.','إشراك الطلاب في أعمال تطوعية مجتمعية تعزز المسؤولية والقيم','جميع طلاب المدرسة','مستمر مع مناسبات وطنية ومجتمعية','رائد النشاط والموجه الطلابي','ذاتية','1. خطة تطوع فصلية مرتبطة بالمناسبات.
2. تسجيل المشاركين وساعات التطوع.
3. تنفيذ الخدمة داخل المدرسة أو المجتمع المحلي.
4. احتفاء وتوثيق في سجل الأنشطة.','مشاركة لا تقل عن 60% من الطلاب في عمل تطوعي واحد على الأقل سنوياً','تعارض الاختبارات يُعاد جدولة النشاط بعد فترة القياس',5,'activity_leader','["3-2-1-4", "1-3-1-3"]',15,'["activity_leader"]','G7');
INSERT INTO "program_templates" VALUES(16,'planning','التخطيط الاستراتيجي','التخطيط الاستراتيجي المدرسي','تطوير منظومة القيادة المدرسية وتفعيل التخطيط الاستراتيجي المبني على البيانات.','استكمال الخطة التشغيلية ومتابعة تنفيذها وفق مؤشرات الأداء','فريق القيادة وأصحاب الخطط','بداية العام مع مراجعات فصلية','مدير المدرسة ولجنة التميز','ذاتية','1. بناء الخطة من بيانات التقويم والتقويم الذاتي.
2. توزيع البرامج على أصحاب الأدوار.
3. متابعة أسبوعية لنسب التنفيذ.
4. تقويم فصلي وتعديل المسار.','اعتماد الخطة في وقتها وتنفيذ لا يقل عن 90% من البرامج التطويرية المخططة','تأخر إدخال البيانات يُعالَج بتجميد موعد الاعتماد واجتماع طارئ للفريق',1,'principal','["1-1-1-1", "1-1-1-2"]',16,'["principal"]','G1');
INSERT INTO "program_templates" VALUES(17,'pd','التطوير المهني','التطوير المهني الداخلي','تطوير الكوادر التعليمية والإدارية مهنيًا وتحسين كفاءتهم.','تلبية احتياجات التطوير المهني وفق نتائج الأداء والزيارات الصفية','المعلمون والإداريون','فصلي وفق خطة التطوير المهني','وكيل الشؤون التعليمية ومدير المدرسة','من برامج الوزارة والتطوير الداخلي','1. تحليل احتياجات من الزيارات والتقويم الوظيفي.
2. ورش داخلية ودروس تطبيقية.
3. متابعة أثر التدريب في الصف.
4. توثيق الحضور في سجل التطوير المهني.','حضور 100% من المعلمين لبرنامج تطويري واحد على الأقل كل فصل','تعارض الاختبارات يُجدول التدريب في أوقات مرنة أو بعد الدوام القصير',2,'vice_teachers','["1-4-1-2"]',17,'["vice_teachers"]','G6');
