INSERT INTO "rules" VALUES(1,'task_overdue','مهمة يومية متأخرة عن تاريخ الاستحقاق وغير مكتملة','عالية','راجع المهمة المتأخرة وأنهِها أو أعد جدولتها اليوم.','board:tasks-today','all','تأخر مهمة','فتح لوحة المهام',1,'2026-10-30T21:36:23.459484+00:00');
INSERT INTO "rules" VALUES(2,'task_evidence_missing','مهمة مستحقة أو قيد التنفيذ وشاهدها ناقص','متوسطة','ارفع شاهد المهمة أو وثّق المرفق قبل إغلاقها.','board:tasks-today','all','شاهد ناقص','استكمال الشاهد',1,'2026-10-30T21:36:23.459484+00:00');
INSERT INTO "rules" VALUES(3,'soft_no_media','فترة لاصفية منفّذة بلا مرفق بصري','عالية','أرفق صورة/ملفًا أو اطبع بطاقة الشاهد للفترة المنفّذة.','board:soft-periods','all','فترة بلا مرفق','فتح متابعة اللاصفية',1,'2026-10-30T21:36:23.459484+00:00');
INSERT INTO "rules" VALUES(4,'soft_today_pending','فترة لاصفية لليوم بلا حالة تنفيذ','متوسطة','حدّث حالة تنفيذ فترات اليوم (اصطفاف/استراحة/صلاة).','board:soft-periods','all','فترة بلا مرفق','تعبئة متابعة اليوم',1,'2026-10-30T21:36:23.459484+00:00');
INSERT INTO "rules" VALUES(5,'indicator_below','مؤشر اعتماد بدرجة دون عتبة 60','عالية','راجع المؤشر الضعيف واربطه ببرنامج أو إجراء تحسين.','board:indicators','principal,vice_teachers','مؤشر دون عتبة','فتح إطار المؤشرات',1,'2026-10-30T21:36:23.459484+00:00');
INSERT INTO "rules" VALUES(6,'improvement_stalled','إجراء تحسين متعثر أو بلا تقدّم','متوسطة','افتح الإجراء المتعثر وحدّث نسبة الإنجاز أو الشاهد.','board:improvement','all','تأخر مهمة','فتح إجراءات التحسين',1,'2026-10-30T21:36:23.459484+00:00');
INSERT INTO "rules" VALUES(7,'program_no_progress','برنامج معتمد بلا قراءة حالية للمؤشر','منخفضة','حدّث القراءة الحالية لمؤشر البرنامج المعتمد.','board:programs','all','مؤشر دون عتبة','فتح البرامج',1,'2026-10-30T21:36:23.459484+00:00');
