            ON phrase_bank(category, sub_category, field_name)
            ;
CREATE INDEX idx_soft_follow_week
            ON soft_period_follow(week_start, day_iso)
            ;
CREATE INDEX idx_visual_evidence_entity
            ON visual_evidence(entity_type, entity_key)
            ;
CREATE INDEX idx_signals_day ON signals(signal_day, severity);
CREATE INDEX idx_signal_actions_fp ON signal_actions(fingerprint, created_at);
CREATE UNIQUE INDEX ux_internal_assignments_active
        ON internal_assignments(assignment_type, academic_year)
        WHERE active = 1
        ;
CREATE INDEX idx_program_images_program
        ON program_images(program_id, sort_order, id)
        ;
